select public._wave7_upsert_formula_tools('saas-tools','[{"slug":"gross-revenue-retention-calculator","title_ar":"حاسبة الاحتفاظ الإجمالي بالإيراد","title_en":"Gross Revenue Retention Calculator","expression":"(starting_mrr - churned_mrr - contraction_mrr) / starting_mrr * 100","fields":["starting_mrr","churned_mrr","contraction_mrr"],"nonzero":["starting_mrr"],"sort_order":15051},{"slug":"saas-expansion-mrr-rate-calculator","title_ar":"حاسبة معدل توسع MRR","title_en":"SaaS Expansion MRR Rate Calculator","expression":"expansion_mrr / starting_mrr * 100","fields":["expansion_mrr","starting_mrr"],"nonzero":["starting_mrr"],"sort_order":15052},{"slug":"saas-activation-rate-calculator","title_ar":"حاسبة معدل تفعيل المستخدمين","title_en":"SaaS Activation Rate Calculator","expression":"activated_users / new_users * 100","fields":["activated_users","new_users"],"nonzero":["new_users"],"sort_order":15053},{"slug":"saas-trial-conversion-rate-calculator","title_ar":"حاسبة تحويل التجربة إلى اشتراك","title_en":"SaaS Trial Conversion Rate Calculator","expression":"paid_customers / trial_users * 100","fields":["paid_customers","trial_users"],"nonzero":["trial_users"],"sort_order":15054},{"slug":"saas-freemium-conversion-rate-calculator","title_ar":"حاسبة تحويل المجاني إلى مدفوع","title_en":"SaaS Freemium Conversion Rate Calculator","expression":"paid_users / free_users * 100","fields":["paid_users","free_users"],"nonzero":["free_users"],"sort_order":15055},{"slug":"saas-support-tickets-per-customer-calculator","title_ar":"حاسبة تذاكر الدعم لكل عميل","title_en":"SaaS Support Tickets per Customer Calculator","expression":"support_tickets / customers","fields":["support_tickets","customers"],"nonzero":["customers"],"sort_order":15056},{"slug":"saas-infrastructure-cost-per-customer-calculator","title_ar":"حاسبة تكلفة البنية لكل عميل","title_en":"SaaS Infrastructure Cost per Customer Calculator","expression":"infrastructure_cost / customers","fields":["infrastructure_cost","customers"